26	  // runZonedGuarded wraps Dart-side async errors so Crashlytics can record
27	  // anything Flutter's own error handlers don't see (top-level async, isolate
28	  // boundaries, microtask queue).
29	  await runZonedGuarded(() async {
30	    WidgetsFlutterBinding.ensureInitialized();
31	    await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
32	
33	    // Crashlytics: collect in release only by default. In debug we want
34	    // crashes to surface in the console + IDE, not get swallowed by upload.
35	    // Override with --dart-define=FORCE_CRASHLYTICS=true if you need to test
36	    // the upload path locally.
37	    const forceCrashlytics = bool.fromEnvironment('FORCE_CRASHLYTICS', defaultValue: false);
38	    await FirebaseCrashlytics.instance
39	        .setCrashlyticsCollectionEnabled(!kDebugMode || forceCrashlytics);
40	
41	    // Send Flutter framework errors (build/layout/paint) to Crashlytics.
42	    FlutterError.onError = FirebaseCrashlytics.instance.recordFlutterFatalError;
43	    // Send uncaught platform-dispatcher errors (async gaps, native bridge).
44	    PlatformDispatcher.instance.onError = (error, stack) {
45	      FirebaseCrashlytics.instance.recordError(error, stack, fatal: true);
46	      return true;
47	    };
48	
49	    if (kDebugMode) {
50	      await _useLocalEmulators();
51	    }
52	    runApp(const ProviderScope(child: DroneAidApp()));
53	  }, (error, stack) {
54	    FirebaseCrashlytics.instance.recordError(error, stack, fatal: true);
55	  });
56	}
