59	  // Android emulator reaches host loopback via 10.0.2.2.
60	  final host = Platform.isAndroid ? '10.0.2.2' : 'localhost';
61	  await FirebaseAuth.instance.useAuthEmulator(host, 9099);
62	  FirebaseFirestore.instance.useFirestoreEmulator(host, 8080);
