41	/// Pure diff helper — produces the sparse patch the `updateProfile` callable
42	/// expects. Only fields whose value actually changed appear in the result.
43	@visibleForTesting
44	Map<String, dynamic> buildProfilePatch({
45	  required UserProfile initial,
46	  required String name,
47	  required String phone,
48	  required double? lat,
49	  required double? lng,
50	  required String label,
51	  double? hubLat,
52	  double? hubLng,
53	  String hubLabel = '',
54	  required String theme,
55	  required bool notificationsEnabled,
56	}) {
57	  final patch = <String, dynamic>{};
58	
59	  if (name.trim() != (initial.name ?? '')) {
60	    patch['name'] = name.trim();
61	  }
62	  if (phone.trim() != (initial.phone ?? '')) {
63	    patch['phone'] = phone.trim();
64	  }
65	
66	  if (lat != null && lng != null) {
67	    final addr = initial.deliveryAddress;
68	    final origLat = (addr?['lat'] as num?)?.toDouble();
69	    final origLng = (addr?['lng'] as num?)?.toDouble();
70	    final origLabel = (addr?['label'] as String?) ?? '';
71	    final trimmedLabel = label.trim();
72	    final changed = addr == null
73	        || origLat != lat
74	        || origLng != lng
75	        || origLabel != trimmedLabel;
76	    if (changed) {
77	      patch['deliveryAddress'] = {
78	        'lat': lat,
79	        'lng': lng,
80	        if (trimmedLabel.isNotEmpty) 'label': trimmedLabel,
81	      };
82	    }
83	  }
84	
85	  if (hubLat != null && hubLng != null) {
86	    final hub = initial.hubLocation;
87	    final origLat = (hub?['lat'] as num?)?.toDouble();
88	    final origLng = (hub?['lng'] as num?)?.toDouble();
89	    final origLabel = (hub?['label'] as String?) ?? '';
90	    final trimmedLabel = hubLabel.trim();
91	    final changed = hub == null
92	        || origLat != hubLat
93	        || origLng != hubLng
94	        || origLabel != trimmedLabel;
95	    if (changed) {
96	      patch['hubLocation'] = {
97	        'lat': hubLat,
98	        'lng': hubLng,
99	        if (trimmedLabel.isNotEmpty) 'label': trimmedLabel,
100	      };
101	    }
102	  }
103	
104	  final prefsChanged =
105	      theme != initial.theme || notificationsEnabled != initial.notificationsEnabled;
106	  if (prefsChanged) {
107	    patch['prefs'] = {
108	      'theme': theme,
109	      'notificationsEnabled': notificationsEnabled,
110	    };
111	  }
112	
113	  return patch;
114	}
